39	      // Get user's team membership (prefer owned team, fallback to any team)
40	      const { data: allMemberships } = await (supabase as any)
41	        .from("team_members")
42	        .select("team_id, role")
43	        .eq("user_id", userId)
44	        .order("role");
45	
46	      // Pick the team where user is owner first, otherwise first membership
47	      const memberships = (allMemberships ?? []) as { team_id: string; role: string }[];
48	      const tmData = memberships.find((m) => m.role === "owner") ?? memberships[0] ?? null;
49	
50	      if (!tmData?.team_id) return { team: null, members: [], invitations: [], myRole: null };
51	
52	      const teamId = tmData.team_id;
53	
54	      // Fetch team, members, invitations in parallel
55	      const [teamRes, membersRes, invitationsRes] = await Promise.all([
56	        (supabase as any).from("teams").select("id, name, owner_id").eq("id", teamId).single(),
57	        (supabase as any).from("team_members").select("id, user_id, role, joined_at").eq("team_id", teamId).order("joined_at"),
58	        (supabase as any).from("team_invitations").select("id, email, role, status, created_at, expires_at").eq("team_id", teamId).eq("status", "pending").order("created_at", { ascending: false }),
59	      ]);
60	
61	      const team: Team | null = teamRes.data ?? null;
62	      const rawMembers = (membersRes.data ?? []) as TeamMember[];
63	      const invitations = (invitationsRes.data ?? []) as TeamInvitation[];
64	
65	      // Augment current user's own record with their email; others show user_id until
