import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface AgencyClient {
  id: string;
  team_id: string;
  company_name: string;
  industry: string | null;
  website: string | null;
  logo_url: string | null;
  sla_days: number | null;
  status: "active" | "inactive" | "churned";
  notes: string | null;
  created_at: string;
}

export interface AgencyContact {
  id: string;
  client_id: string;
  name: string;
  email: string | null;
  phone: string | null;
  role: string | null;
  is_primary: boolean;
  created_at: string;
}

export type CreateClientInput = Omit<AgencyClient, "id" | "created_at">;
export type UpdateClientInput = Partial<CreateClientInput> & { id: string };

export type CreateContactInput = Omit<AgencyContact, "id" | "created_at">;

// ─── Clients hook ─────────────────────────────────────────────────────────────

export function useAgencyClients(teamId: string | null) {
  const queryClient = useQueryClient();
  const queryKey = ["agency_clients", teamId];

  const { data, isLoading, error } = useQuery({
    queryKey,
    queryFn: async (): Promise<AgencyClient[]> => {
      if (!teamId) return [];
      try {
        const { data, error } = await (supabase as any)
          .from("agency_clients")
          .select("*")
          .eq("team_id", teamId)
          .order("created_at", { ascending: false });
        if (error) throw error;
        return (data ?? []) as AgencyClient[];
      } catch {
        return [];
      }
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  const createClient = useMutation({
    mutationFn: async (input: Omit<CreateClientInput, "team_id">) => {
      if (!teamId) throw new Error("No team");
      const { data, error } = await (supabase as any)
        .from("agency_clients")
        .insert({ ...input, team_id: teamId })
        .select()
        .single();
      if (error) throw error;
      return data as AgencyClient;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Client added");
    },
    onError: (err: Error) => {
      toast.error(`Failed to add client: ${err.message}`);
    },
  });

  const updateClient = useMutation({
    mutationFn: async ({ id, ...updates }: UpdateClientInput) => {
      const { data, error } = await (supabase as any)
        .from("agency_clients")
        .update(updates)
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data as AgencyClient;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Client updated");
    },
    onError: (err: Error) => {
      toast.error(`Failed to update client: ${err.message}`);
    },
  });

  const deleteClient = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any)
        .from("agency_clients")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Client deleted");
    },
    onError: (err: Error) => {
      toast.error(`Failed to delete client: ${err.message}`);
    },
  });

  return {
    clients: data ?? [],
    isLoading,
    error,
    createClient,
    updateClient,
    deleteClient,
  };
}

// ─── Contacts hook ────────────────────────────────────────────────────────────

export function useAgencyContacts(clientId: string | null) {
  const queryClient = useQueryClient();
  const queryKey = ["agency_contacts", clientId];

  const { data, isLoading } = useQuery({
    queryKey,
    queryFn: async (): Promise<AgencyContact[]> => {
      if (!clientId) return [];
      try {
        const { data, error } = await (supabase as any)
          .from("agency_contacts")
          .select("*")
          .eq("client_id", clientId)
          .order("is_primary", { ascending: false });
        if (error) throw error;
        return (data ?? []) as AgencyContact[];
      } catch {
        return [];
      }
    },
    enabled: !!clientId,
    staleTime: 30_000,
  });

  const createContact = useMutation({
    mutationFn: async (input: CreateContactInput) => {
      const { data, error } = await (supabase as any)
        .from("agency_contacts")
        .insert(input)
        .select()
        .single();
      if (error) throw error;
      return data as AgencyContact;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
