import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface AgencyCommission {
  id: string;
  placement_id: string;
  user_id: string;
  amount: number;
  percentage: number;
  status: "pending" | "approved" | "paid";
  period: string | null;
  created_at: string;
  // Joined
  candidate_name?: string;
  user_email?: string;
}

export interface CommissionTotals {
  earned: number;
  pending: number;
  paid: number;
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useAgencyCommissions(teamId: string | null) {
  const queryKey = ["agency_commissions", teamId];

  const { data, isLoading, error } = useQuery({
    queryKey,
    queryFn: async (): Promise<{ commissions: AgencyCommission[]; totals: CommissionTotals }> => {
      if (!teamId) return { commissions: [], totals: { earned: 0, pending: 0, paid: 0 } };
      try {
        const { data, error } = await (supabase as any)
          .from("agency_commissions")
          .select("*, agency_placements(candidate_name)")
          .order("created_at", { ascending: false });
        if (error) throw error;

        const rows = ((data ?? []) as any[]).map((row) => ({
          ...row,
          candidate_name: row.agency_placements?.candidate_name ?? null,
          agency_placements: undefined,
        })) as AgencyCommission[];

        const totals: CommissionTotals = {
          earned: rows.reduce((s, r) => s + (r.amount ?? 0), 0),
          pending: rows
            .filter((r) => r.status === "pending")
            .reduce((s, r) => s + (r.amount ?? 0), 0),
          paid: rows
            .filter((r) => r.status === "paid")
            .reduce((s, r) => s + (r.amount ?? 0), 0),
        };

        return { commissions: rows, totals };
      } catch {
        return { commissions: [], totals: { earned: 0, pending: 0, paid: 0 } };
      }
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  return {
    commissions: data?.commissions ?? [],
    totals: data?.totals ?? { earned: 0, pending: 0, paid: 0 },
    isLoading,
    error,
  };
}

