function fmtDate(d: string | null) {
  if (!d) return "—";
  try {
    return format(parseISO(d), "MMM d, yyyy");
  } catch {
    return "—";
  }
}

function fmtCurrency(amount: number | null, currency = "USD") {
  if (amount == null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(amount);
}

function GuarantyBadge({ expiresAt }: { expiresAt: string | null }) {
  if (!expiresAt) return <span className="text-muted-foreground text-xs">—</span>;
  const days = differenceInDays(parseISO(expiresAt), new Date());
  if (days < 0) return <Badge variant="destructive" className="text-[10px]">Expired</Badge>;
  if (days <= 7) return <Badge variant="destructive" className="text-[10px]">{days}d left</Badge>;
  return <Badge variant="secondary" className="text-[10px]">{days}d left</Badge>;
}

