function ClientsTab({ teamId }: { teamId: string }) {
  const { clients, isLoading, createClient, updateClient, deleteClient } = useAgencyClients(teamId);
  const { mandates } = useAgencyMandates(teamId);
  const { placements } = useAgencyPlacements(teamId);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [addOpen, setAddOpen] = useState(false);
  const [editClient, setEditClient] = useState<AgencyClient | null>(null);

  const [form, setForm] = useState({
    company_name: "",
    industry: "",
    website: "",
    sla_days: "",
    notes: "",
    status: "active" as AgencyClient["status"],
  });

  function resetForm() {
    setForm({ company_name: "", industry: "", website: "", sla_days: "", notes: "", status: "active" });
  }

  function openEdit(c: AgencyClient) {
    setEditClient(c);
    setForm({
      company_name: c.company_name,
      industry: c.industry ?? "",
      website: c.website ?? "",
      sla_days: c.sla_days?.toString() ?? "",
      notes: c.notes ?? "",
      status: c.status,
    });
  }

  async function handleSubmit() {
    if (!form.company_name.trim()) {
      toast.error("Company name is required");
      return;
    }
    const payload = {
      company_name: form.company_name.trim(),
      industry: form.industry.trim() || null,
      website: form.website.trim() || null,
      logo_url: null,
      sla_days: form.sla_days ? parseInt(form.sla_days) : null,
      notes: form.notes.trim() || null,
      status: form.status,
    };
    if (editClient) {
      await updateClient.mutateAsync({ id: editClient.id, ...payload });
      setEditClient(null);
    } else {
      await createClient.mutateAsync(payload);
      setAddOpen(false);
    }
    resetForm();
  }

  const filtered = useMemo(() => {
    return clients.filter((c) => {
      const matchSearch =
        !search ||
        c.company_name.toLowerCase().includes(search.toLowerCase()) ||
        (c.industry ?? "").toLowerCase().includes(search.toLowerCase());
      const matchStatus = statusFilter === "all" || c.status === statusFilter;
      return matchSearch && matchStatus;
    });
  }, [clients, search, statusFilter]);

  const activeCount = clients.filter((c) => c.status === "active").length;

  const mandateCountFor = (clientId: string) =>
    mandates.filter((m) => m.client_id === clientId && m.status !== "cancelled").length;
  const placementCountFor = (clientId: string) =>
    placements.filter((p) => p.client_id === clientId).length;

  const DialogBody = (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <div className="sm:col-span-2 space-y-1.5">
        <Label>Company Name *</Label>
        <Input
          value={form.company_name}
          onChange={(e) => setForm((f) => ({ ...f, company_name: e.target.value }))}
          placeholder="Acme Recruiting Ltd"
        />
      </div>
      <div className="space-y-1.5">
        <Label>Industry</Label>
        <Input
          value={form.industry}
          onChange={(e) => setForm((f) => ({ ...f, industry: e.target.value }))}
          placeholder="Technology, Finance..."
        />
      </div>
      <div className="space-y-1.5">
        <Label>Website</Label>
        <Input
          value={form.website}
          onChange={(e) => setForm((f) => ({ ...f, website: e.target.value }))}
          placeholder="https://acme.com"
        />
      </div>
      <div className="space-y-1.5">
        <Label>SLA Days</Label>
        <Input
          type="number"
          value={form.sla_days}
          onChange={(e) => setForm((f) => ({ ...f, sla_days: e.target.value }))}
          placeholder="30"
          min={1}
        />
      </div>
      <div className="space-y-1.5">
