              <EmptyRow cols={8} message={clients.length === 0 ? "No clients yet. Add your first client." : "No clients match your filter."} />
            ) : (
              filtered.map((c) => (
                <TableRow key={c.id} className="hover:bg-muted/30 transition-colors">
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-muted text-xs font-semibold">
                        {c.company_name.charAt(0).toUpperCase()}
                      </div>
                      <span className="font-medium text-sm">{c.company_name}</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">{c.industry ?? "—"}</TableCell>
                  <TableCell><StatusBadge status={c.status} /></TableCell>
                  <TableCell className="text-sm">{c.sla_days ? `${c.sla_days}d` : "—"}</TableCell>
                  <TableCell className="text-sm">{mandateCountFor(c.id)}</TableCell>
                  <TableCell className="text-sm">{placementCountFor(c.id)}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">{fmtDate(c.created_at)}</TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => openEdit(c)}
