function PlacementsTab({ teamId }: { teamId: string }) {
  const { placements, isLoading, createPlacement, updatePlacement } = useAgencyPlacements(teamId);
  const { mandates } = useAgencyMandates(teamId);
  const { clients } = useAgencyClients(teamId);

  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({
    mandate_id: "",
    client_id: "",
    candidate_name: "",
    candidate_email: "",
    salary: "",
    fee_amount: "",
    start_date: "",
    guarantee_days: "",
    status: "offered" as AgencyPlacement["status"],
  });

  function resetForm() {
    setForm({ mandate_id: "", client_id: "", candidate_name: "", candidate_email: "", salary: "", fee_amount: "", start_date: "", guarantee_days: "", status: "offered" });
  }

  // Auto-fill client from mandate selection
  function onMandateChange(mandateId: string) {
    const mandate = mandates.find((m) => m.id === mandateId);
    setForm((f) => ({
      ...f,
      mandate_id: mandateId,
      client_id: mandate?.client_id ?? f.client_id,
    }));
  }

  async function handleSubmit() {
    if (!form.mandate_id) { toast.error("Select a mandate"); return; }
    if (!form.candidate_name.trim()) { toast.error("Candidate name is required"); return; }
    const guarDays = form.guarantee_days ? parseInt(form.guarantee_days) : null;
    const startDate = form.start_date || null;
    const guarExpires = guarDays && startDate
      ? format(addDays(parseISO(startDate), guarDays), "yyyy-MM-dd")
      : null;

    await createPlacement.mutateAsync({
      mandate_id: form.mandate_id,
      client_id: form.client_id,
      candidate_name: form.candidate_name.trim(),
      candidate_email: form.candidate_email.trim() || null,
      salary: form.salary ? parseFloat(form.salary) : null,
      fee_amount: form.fee_amount ? parseFloat(form.fee_amount) : null,
      start_date: startDate,
      guarantee_days: guarDays,
      guarantee_expires_at: guarExpires,
      status: form.status,
    });
    setAddOpen(false);
    resetForm();
  }

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <Button onClick={() => { resetForm(); setAddOpen(true); }} className="gap-1.5">
