                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">{p.client_name ?? "—"}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">{p.mandate_title ?? "—"}</TableCell>
                  <TableCell>
                    <Select
                      value={p.status}
                      onValueChange={(v) =>
                        updatePlacement.mutate({ id: p.id, status: v as AgencyPlacement["status"] })
                      }
                    >
                      <SelectTrigger className="h-7 w-[110px] text-xs border-none shadow-none px-2">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="offered">Offered</SelectItem>
                        <SelectItem value="accepted">Accepted</SelectItem>
                        <SelectItem value="started">Started</SelectItem>
                        <SelectItem value="guarantee">In Guarantee</SelectItem>
                        <SelectItem value="completed">Completed</SelectItem>
                        <SelectItem value="fallen_off">Fallen Off</SelectItem>
                      </SelectContent>
                    </Select>
                  </TableCell>
                  <TableCell className="text-sm">{fmtDate(p.start_date)}</TableCell>
                  <TableCell className="text-sm">{fmtCurrency(p.salary)}</TableCell>
                  <TableCell className="text-sm">{fmtCurrency(p.fee_amount)}</TableCell>
                  <TableCell><GuarantyBadge expiresAt={p.guarantee_expires_at} /></TableCell>
                  <TableCell />
