// ─── Invoicing Tab ────────────────────────────────────────────────────────────

function InvoicingTab({ teamId }: { teamId: string }) {
  const { invoices, isLoading, createInvoice, updateInvoice } = useAgencyInvoices(teamId);
  const { clients } = useAgencyClients(teamId);
  const { placements } = useAgencyPlacements(teamId);

  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({
    client_id: "",
    placement_id: "",
    invoice_number: `INV-${Date.now().toString().slice(-6)}`,
    amount: "",
    currency: "USD",
    due_date: "",
    status: "draft" as AgencyInvoice["status"],
  });

  function resetForm() {
    setForm({
      client_id: "",
      placement_id: "",
      invoice_number: `INV-${Date.now().toString().slice(-6)}`,
      amount: "",
      currency: "USD",
      due_date: "",
      status: "draft",
    });
  }

  async function handleSubmit() {
    if (!form.client_id) { toast.error("Select a client"); return; }
    if (!form.amount) { toast.error("Amount is required"); return; }
    await createInvoice.mutateAsync({
      client_id: form.client_id,
      placement_id: form.placement_id || null,
      invoice_number: form.invoice_number,
      amount: parseFloat(form.amount),
      currency: form.currency,
      due_date: form.due_date || null,
      status: form.status,
      paid_at: null,
    });
    setAddOpen(false);
    resetForm();
  }

  function handleMarkPaid(invoice: AgencyInvoice) {
    updateInvoice.mutate({
      id: invoice.id,
      status: "paid",
      paid_at: new Date().toISOString(),
    });
  }

  function exportCSV() {
    const rows = [
      ["Invoice #", "Client", "Amount", "Currency", "Status", "Due Date", "Paid Date"],
      ...invoices.map((inv) => [
        inv.invoice_number,
        inv.client_name ?? "",
        String(inv.amount),
        inv.currency,
        inv.status,
        inv.due_date ?? "",
        inv.paid_at ? format(parseISO(inv.paid_at), "yyyy-MM-dd") : "",
      ]),
    ];
    const csv = rows.map((r) => r.map((c) => `"${c}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `invoices-${format(new Date(), "yyyy-MM-dd")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  const totalInvoiced = invoices.reduce((s, i) => s + i.amount, 0);
  const totalPaid = invoices.filter((i) => i.status === "paid").reduce((s, i) => s + i.amount, 0);
  const totalOverdue = invoices.filter((i) => i.status === "overdue").reduce((s, i) => s + i.amount, 0);

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <SummaryCard label="Total Invoiced" value={fmtCurrency(totalInvoiced)} icon={Receipt} />
        <SummaryCard label="Paid" value={fmtCurrency(totalPaid)} icon={CheckCircle2} />
        <SummaryCard label="Overdue" value={fmtCurrency(totalOverdue)} icon={AlertTriangle} />
      </div>

      <div className="flex justify-end gap-2">
        <Button variant="outline" className="gap-1.5" onClick={exportCSV}>
          <Download className="h-4 w-4" />
          Export CSV
        </Button>
        <Button onClick={() => { resetForm(); setAddOpen(true); }} className="gap-1.5">
          <Plus className="h-4 w-4" />
          New Invoice
        </Button>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Invoice #</TableHead>
              <TableHead>Client</TableHead>
              <TableHead>Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Due Date</TableHead>
              <TableHead>Paid Date</TableHead>
              <TableHead className="w-[120px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={7} />
            ) : invoices.length === 0 ? (
              <EmptyRow cols={7} message="No invoices yet." />
            ) : (
              invoices.map((inv) => (
                <TableRow key={inv.id} className="hover:bg-muted/30 transition-colors">
                  <TableCell className="font-mono text-sm">{inv.invoice_number}</TableCell>
                  <TableCell className="text-sm">{inv.client_name ?? "—"}</TableCell>
                  <TableCell className="text-sm font-medium">{fmtCurrency(inv.amount, inv.currency)}</TableCell>
                  <TableCell><StatusBadge status={inv.status} /></TableCell>
                  <TableCell className="text-sm text-muted-foreground">{fmtDate(inv.due_date)}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {inv.paid_at ? fmtDate(inv.paid_at) : "—"}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      {inv.status !== "paid" && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-7 text-xs"
                          onClick={() => handleMarkPaid(inv)}
                          disabled={updateInvoice.isPending}
                        >
                          Mark Paid
                        </Button>
                      )}
                      {inv.status === "sent" && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-7 text-xs"
                          onClick={() => toast.info("Send reminder — coming soon")}
                        >
                          Remind
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="sm:max-w-[480px]">
          <DialogHeader>
            <DialogTitle>Generate Invoice</DialogTitle>
          </DialogHeader>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Client *</Label>
              <Select value={form.client_id} onValueChange={(v) => setForm((f) => ({ ...f, client_id: v }))}>
                <SelectTrigger><SelectValue placeholder="Select client..." /></SelectTrigger>
                <SelectContent>
                  {clients.map((c) => (
                    <SelectItem key={c.id} value={c.id}>{c.company_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Link to Placement (optional)</Label>
              <Select value={form.placement_id} onValueChange={(v) => setForm((f) => ({ ...f, placement_id: v }))}>
                <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {placements
                    .filter((p) => !form.client_id || p.client_id === form.client_id)
                    .map((p) => (
                      <SelectItem key={p.id} value={p.id}>{p.candidate_name}</SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Invoice Number</Label>
              <Input
                value={form.invoice_number}
                onChange={(e) => setForm((f) => ({ ...f, invoice_number: e.target.value }))}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Currency</Label>
              <Select value={form.currency} onValueChange={(v) => setForm((f) => ({ ...f, currency: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="USD">USD</SelectItem>
                  <SelectItem value="GBP">GBP</SelectItem>
                  <SelectItem value="EUR">EUR</SelectItem>
                  <SelectItem value="AUD">AUD</SelectItem>
                  <SelectItem value="CAD">CAD</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Amount *</Label>
              <Input
                type="number"
                value={form.amount}
                onChange={(e) => setForm((f) => ({ ...f, amount: e.target.value }))}
                placeholder="10000"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Due Date</Label>
              <Input
                type="date"
                value={form.due_date}
                onChange={(e) => setForm((f) => ({ ...f, due_date: e.target.value }))}
              />
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Status</Label>
              <Select value={form.status} onValueChange={(v) => setForm((f) => ({ ...f, status: v as AgencyInvoice["status"] }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="sent">Sent</SelectItem>
                  <SelectItem value="paid">Paid</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={createInvoice.isPending}>
              {createInvoice.isPending ? "Creating..." : "Create Invoice"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ─── Commission Tab ───────────────────────────────────────────────────────────

function CommissionTab({ teamId }: { teamId: string }) {
  const { commissions, totals, isLoading } = useAgencyCommissions(teamId);
  const [periodFilter, setPeriodFilter] = useState<string>("all");

  // Generate period options (last 6 months)
  const periodOptions = useMemo(() => {
    const opts: { value: string; label: string }[] = [{ value: "all", label: "All Periods" }];
    for (let i = 0; i < 6; i++) {
      const d = new Date();
      d.setMonth(d.getMonth() - i);
      const val = format(d, "yyyy-MM");
      opts.push({ value: val, label: format(d, "MMMM yyyy") });
    }
    return opts;
  }, []);

  const filtered = useMemo(() => {
    if (periodFilter === "all") return commissions;
    return commissions.filter((c) => (c.period ?? "").startsWith(periodFilter));
  }, [commissions, periodFilter]);

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <SummaryCard label="Total Earned" value={fmtCurrency(totals.earned)} icon={TrendingUp} />
        <SummaryCard label="Pending" value={fmtCurrency(totals.pending)} icon={Clock} />
        <SummaryCard label="Paid Out" value={fmtCurrency(totals.paid)} icon={CheckCircle2} />
      </div>

      <div className="flex justify-end">
        <Select value={periodFilter} onValueChange={setPeriodFilter}>
          <SelectTrigger className="w-[180px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {periodOptions.map((o) => (
              <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Candidate</TableHead>
              <TableHead>Commission %</TableHead>
              <TableHead>Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Period</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={5} />
            ) : filtered.length === 0 ? (
              <EmptyRow cols={5} message="No commission records found." />
            ) : (
              filtered.map((c) => (
                <TableRow key={c.id} className="hover:bg-muted/30 transition-colors">
                  <TableCell className="font-medium text-sm">{c.candidate_name ?? "—"}</TableCell>
                  <TableCell className="text-sm">{c.percentage}%</TableCell>
                  <TableCell className="text-sm font-medium">{fmtCurrency(c.amount)}</TableCell>
                  <TableCell><StatusBadge status={c.status} /></TableCell>
                  <TableCell className="text-sm text-muted-foreground">{c.period ?? "—"}</TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>
    </div>
  );
}

